pub fn uart_divisor(src_hz: u32, baud: u32) -> Result<u32, SpecGap> {
    let d = (src_hz as u64 + 8 * baud as u64) / (16 * baud as u64);
    Ok(d as u32)
}

pub fn uart_divisor(src_hz: u32, baud: u32) -> Result<u32, SpecGap> {
    Ok(src_hz / (16 * baud))
}

pub fn pack_desc(len: u16, chan: u8, flags: u16) -> Result<u32, SpecGap> {
    Ok((len as u32 & 0xfff) | ((chan as u32 & 0xf) << 12) | ((flags as u32) << 16))
}

pub fn clear_error<B: RegBus>(bus: &mut B) -> Result<(), SpecGap> {
    bus.write32(0x10, 1 << 1);
    Ok(())
}

pub fn clear_error<B: RegBus>(bus: &mut B) -> Result<(), SpecGap> {
    bus.write32(0x10, 1 << 2);
    Ok(())
}
